function req(array $session,string $path,?array $fields=null):array{global$base;$c=curl_init($base.$path);curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HEADER=>true,CURLOPT_COOKIEJAR=>$session['jar'],CURLOPT_COOKIEFILE=>$session['jar'],CURLOPT_TIMEOUT=>30]);if($fields!==null){curl_setopt($c,CURLOPT_POST,true);curl_setopt($c,CURLOPT_POSTFIELDS,$fields);}$r=curl_exec($c);if($r===false)throw new RuntimeException(curl_error($c));$n=curl_getinfo($c,CURLINFO_HEADER_SIZE);$respuesta=['code'=>curl_getinfo($c,CURLINFO_RESPONSE_CODE),'body'=>substr($r,$n),'headers'=>substr($r,0,$n)];unset($c);return $respuesta;}
function hidden(string $html,string $name):string{preg_match('/name="'.preg_quote($name,'/').'"[^>]*value="([^"]*)"/',$html,$m);return html_entity_decode($m[1]??'',ENT_QUOTES|ENT_HTML5,'UTF-8');}
