function datosFormularioPersonal(string $html):array{
 $dom=new DOMDocument();@$dom->loadHTML($html);$xp=new DOMXPath($dom);$form=$xp->query('//form[input[@name="accion" and @value="guardar"]]')->item(0);if(!$form)throw new RuntimeException('No se encontró formulario Personal');$out=[];
 foreach($xp->query('.//input[@name]|.//select[@name]|.//textarea[@name]',$form)as$el){
  if($el->hasAttribute('disabled'))continue;$name=$el->getAttribute('name');
  if($el->tagName==='input'){if(in_array($el->getAttribute('type'),['checkbox','radio'],true)&&!$el->hasAttribute('checked'))continue;$value=$el->getAttribute('value');}
  elseif($el->tagName==='textarea')$value=$el->textContent;
  else{$opt=$xp->query('.//option[@selected]',$el)->item(0)??$xp->query('.//option',$el)->item(0);$value=$opt?($opt->hasAttribute('value')?$opt->getAttribute('value'):$opt->textContent):'';}
  $out[$name]=$value;
 }return$out;
}
